create table public.launch_promo (id bool, name text, active bool, max_redemptions int4, claimed_redemptions int4, discount_percent numeric, maximum_discount numeric, starts_at timestamptz, created_at timestamptz, updated_at timestamptz);
create table public.launch_promo_reservations (id uuid default gen_random_uuid(), checkout_session_id uuid, status text, reserved_at timestamptz, expires_at timestamptz, claimed_at timestamptz, order_id uuid, eligible_subtotal numeric, discount_amount numeric, claim_kind text, created_at timestamptz, updated_at timestamptz);
create table public.order_items (id uuid default gen_random_uuid(), order_id uuid, product_id uuid, product_name text, price_snapshot numeric, quantity int4, line_total numeric, variant_id uuid, variant_group_name text, variant_name text, is_clearance bool);
create table public.orders (id uuid default gen_random_uuid(), order_reference text, idempotency_key uuid, customer_name text, mobile_number text, house_unit text, street text, barangay text, city_municipality text, region text, postal_code text, order_notes text, delivery_method text, payment_method text, merchandise_subtotal numeric, shipping_fee numeric, cod_service_fee numeric, upfront_amount numeric, rider_collectible_amount numeric, showroom_payable_amount numeric, overall_total numeric, shipping_classification text, payment_proof_path text, payment_status text, order_status text, internal_admin_note text, reservation_deadline timestamptz, created_at timestamptz, updated_at timestamptz, selected_payment_option_id uuid, selected_payment_option_name text, telegram_notification_status text, telegram_notification_sent_at timestamptz, telegram_notification_attempted_at timestamptz, telegram_notification_error text, telegram_notification_type text, is_test_order bool, archived_at timestamptz, first_name text, last_name text, promo_name text, promo_discount numeric, promo_eligible_subtotal numeric, promo_redemption_number int4, shipping_tier text, same_day_processing text, rider_ready_at timestamptz, courier text, tracking_number text);
create table public.product_variants (id uuid default gen_random_uuid(), product_id uuid, name text, price numeric, stock int4, sku text, image_url text, sort_order int4, created_at timestamptz, updated_at timestamptz);
create table public.products (id uuid default gen_random_uuid(), name text, slug text, brand text, category text, price numeric, stock int4, status text, short_description text, description text, specifications jsonb, image_urls text[], featured bool, is_active bool, created_at timestamptz, updated_at timestamptz, shipping_classification text, show_on_homepage bool, highlight_type text, homepage_sort_order int4, has_variants bool, variant_group_name text, product_type text, is_clearance bool, shipping_class text, is_best_seller bool);
